def hidden_rule_fn(state):
    next_state = []
    for i in range(15):
        r, c = divmod(i, 5)
        v = state[i]
        if r % 2 == 0:
            right_val = state[r * 5 + (c + 1) % 5]
            next_state.append((v + right_val) % 5)
        else:
            below_val = state[(r + 1) * 5 + c]
            next_state.append((v ^ below_val) % 5)
    return next_state
